package com.commercecore.wishlist;import com.commercecore.cart.CartDtos;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController@RequestMapping("/api/v1/wishlist")@SecurityRequirement(name="bearerAuth")public class WishlistController{private final WishlistService wishlist;public WishlistController(WishlistService w){wishlist=w;}@GetMapping WishlistDtos.WishlistResponse get(@AuthenticationPrincipal Jwt jwt){return wishlist.get(user(jwt));}@PostMapping("/items")ResponseEntity<WishlistDtos.WishlistResponse> add(@AuthenticationPrincipal Jwt jwt,@Valid@RequestBody WishlistDtos.AddRequest r){return ResponseEntity.status(201).body(wishlist.add(user(jwt),r));}@DeleteMapping("/items/{id}")WishlistDtos.WishlistResponse remove(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){return wishlist.remove(user(jwt),id);}@PostMapping("/items/{id}/move-to-cart")CartDtos.CartResponse move(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id,@Valid@RequestBody WishlistDtos.MoveRequest r){return wishlist.moveToCart(user(jwt),id,r.quantity());}private static UUID user(Jwt jwt){return UUID.fromString(jwt.getSubject());}}
